extends Node
var fails := 0
var cases := 0
func check(label: String, yes: bool) -> void:
 cases += 1
 if not yes: fails += 1
 print("CENSUS_REPLAY %s %s" % [label,"ok" if yes else "FAIL"])
# Independent physical occupancy. Does not materialise a slice or initialise any working cache.
func cells_volume(t: ChopTree) -> float:
 var w := t.wood_model()
 var sum := 0.0
 for i in w.slices:
  var bits := w.bits_of(i)
  if bits.is_empty(): bits = w._disks[roundi(w.radius_of(i)/w.cell*8.0)][0]
  var n := 0
  for word: int in bits: n += WoodCuts.popcount(word)
  sum += n*w.cell_volume()
 return sum
func _ready() -> void:
 var defs := Grove.plan()
 for id: int in [3,8,1]:
  var a := ChopTree.new()
  var b := ChopTree.new()
  Grove.apply(a,defs[id]);Grove.apply(b,defs[id])
  var wa := a.wood_model()
  var wb := b.wood_model()
  for hit in 12:
   var h := 0.75+(hit%3)*0.017
   var d := Vector2.from_angle(hit*1.13)
   var side := Vector3(d.x,0,d.y)
   var across := side.cross(Vector3.UP)
   var r := a.bark_radius(h)
   var planes := WoodCuts.pack([Plane(side,r*(0.4-0.13*hit)),Plane(-side,r+0.01),Plane(across,r+0.01),Plane(-across,r+0.01),Plane(Vector3.UP,h+0.031),Plane(Vector3.DOWN,-h+0.023)])
   var fine0 := wb._fine.duplicate(true)
   var coarse0 := wb._coarse.duplicate(true)
   var disks0 := wb._disks.duplicate(true)
   var counts0 := wb._count.duplicate()
   # Only B is censused, repeatedly, before each fixed input operation.
   for sample in 3:
    b.matter_kg()
    cells_volume(b)
   check("observer_pure_%d_%d" % [id,hit],wb._fine==fine0 and wb._coarse==coarse0 and wb._disks==disks0 and wb._count==counts0)
   var before := cells_volume(b)
   var removed0 := wb.removed
   wa.apply(planes);wb.apply(planes)
   check("same_fine_coarse_%d_%d" % [id,hit],wa._fine==wb._fine and wa._coarse==wb._coarse and wa._count==wb._count and wa.removed==wb.removed)
   check("exact_transfer_%d_%d" % [id,hit],absf(cells_volume(b)+(wb.removed-removed0)*wb.cell_volume()-before)<1e-12)
   var mask_a := wa.fibres(h,0.1)
   var mask_b := wb.fibres(h,0.1)
   var stress_a := wa.stress_of(mask_a,r,1000.0,Vector2(0.1,0.0),40e6)
   var stress_b := wb.stress_of(mask_b,r,1000.0,Vector2(0.1,0.0),40e6)
   check("same_stress_%d_%d" % [id,hit],mask_a==mask_b and stress_a==stress_b)
  a.free();b.free()
 print("CENSUS_REPLAY_DONE cases=%d fails=%d" % [cases,fails])
 get_tree().quit(0 if fails==0 else 1)
GD
